using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
public class MinutePoint {public DateTime Utc;public Dictionary<string,double> Values=new Dictionary<string,double>();}
public sealed class MinuteHistory {
 readonly string folder;readonly object gate=new object();readonly Dictionary<string,List<MinutePoint>> days=new Dictionary<string,List<MinutePoint>>();readonly HashSet<string> blocked=new HashSet<string>(),dirty=new HashSet<string>();DateTime lastMinute,flushed;public string Status="分钟采样从启用后开始";
 static readonly string[] Keys={"cpu","gpu","memory","cpuTemp","gpuTemp","disk","download","upload","diskRead","diskWrite","frequency","codex5h","codex7d","diskTemp","vram","memoryUsed","memoryAvailable","vramUsed","vramTotal"};
 public MinuteHistory(string data){folder=Path.Combine(data,"monitor-history-minute");}
 static string Day(DateTime t){return t.ToUniversalTime().ToString("yyyy-MM-dd");}
 List<MinutePoint> Load(string day){List<MinutePoint> result;if(days.TryGetValue(day,out result))return result;result=new List<MinutePoint>();string path=Path.Combine(folder,day+".json");try{if(File.Exists(path)){if(new FileInfo(path).Length>8388608)throw new IOException("分钟历史文件过大");result=new JavaScriptSerializer{MaxJsonLength=8388608}.Deserialize<List<MinutePoint>>(File.ReadAllText(path));if(result==null||result.Any(p=>p==null||p.Values==null))throw new InvalidDataException("分钟历史格式无效");}}catch(Exception e){if(!(e is IOException)&&!(e is InvalidDataException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is UnauthorizedAccessException))throw;blocked.Add(day);Status="分钟历史无法读取，原文件已保留："+day;result=new List<MinutePoint>();}days[day]=result;return result;}
 public void Observe(SystemSample s){if(s==null||s.Utc==default(DateTime))return;lock(gate){DateTime utc=s.Utc.ToUniversalTime(),minute=new DateTime(utc.Year,utc.Month,utc.Day,utc.Hour,utc.Minute,0,DateTimeKind.Utc);if(minute<=lastMinute)return;lastMinute=minute;string day=Day(minute);var points=Load(day);if(blocked.Contains(day))return;var point=new MinutePoint{Utc=minute};foreach(string key in Keys){double? v=key=="memoryUsed"?(s.MemoryTotal>0?(double?)s.MemoryUsed:null):key=="memoryAvailable"?(s.MemoryTotal>0?(double?)(s.MemoryTotal-s.MemoryUsed):null):key=="vramUsed"?s.VramUsed/1024:key=="vramTotal"?s.VramTotal/1024:key=="diskTemp"?s.DiskTemperature:key=="vram"?(s.VramTotal>0?s.VramUsed/s.VramTotal*100:null):MonitorEngine.Value(s,key);if((key=="gpu"||key=="gpuTemp"||key=="vram")&&s.GpuSampleUtc!=default(DateTime)&&(s.Utc-s.GpuSampleUtc).TotalSeconds>5)continue;if(v.HasValue&&!Double.IsNaN(v.Value)&&!Double.IsInfinity(v.Value)&&v>=0)point.Values[key]=v.Value;}if(point.Values.Count>0){int existing=points.FindIndex(p=>p.Utc==minute);if(existing>=0)points[existing]=point;else points.Add(point);dirty.Add(day);}if((utc-flushed).TotalSeconds>=60)Flush();}}
 public MinutePoint[] Range(DateTime start,DateTime end){lock(gate){DateTime a=start.ToUniversalTime(),b=end.ToUniversalTime();for(DateTime d=a.Date;d<b;d=d.AddDays(1))Load(Day(DateTime.SpecifyKind(d,DateTimeKind.Utc)));return days.Values.SelectMany(x=>x).Where(p=>p.Utc>=a&&p.Utc<b).OrderBy(p=>p.Utc).Select(p=>new MinutePoint{Utc=p.Utc,Values=new Dictionary<string,double>(p.Values)}).ToArray();}}
 public void Flush(){lock(gate){try{Directory.CreateDirectory(folder);}catch(IOException){Status="分钟历史目录不可写";return;}catch(UnauthorizedAccessException){Status="分钟历史目录不可写";return;}foreach(string day in dirty.ToArray()){if(blocked.Contains(day))continue;string path=Path.Combine(folder,day+".json"),temp=path+".tmp";try{File.WriteAllText(temp,new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(days[day]),new System.Text.UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);dirty.Remove(day);}catch(IOException){Status="分钟历史保存失败，内存记录保留";}catch(UnauthorizedAccessException){Status="分钟历史保存失败，内存记录保留";}}flushed=DateTime.UtcNow;}}
}
